mapper.select:
select t2.name as productName, t.ip, t.public_ip as publicIp, t.ip_address as ipAddress, CASE WHEN t.status = 0 THEN '未使用' WHEN t.status = 1 THEN '已使用' WHEN t.status = 2 THEN '等待中' ELSE '未知类型' END AS status, t3.customer_name as nickname, t.email from sys_network_product_ip t left join sys_network_product t2 on t.product_id = t2.id left join sys_customer t3 on t.user_id = t3.id
and t.product_id = #{param.productId}
and t.status = #{param.status}
and t.email like concat ('%',#{param.email},'%')
and t.ip like concat ('%',#{param.ip},'%')
and t.public_ip like concat ('%',#{param.publicIp},'%')
and t3.customer_name like concat ('%',#{param.customerName},'%')
and t.id in
#{id}
